1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #e9ebef;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    padding: 16px;
22	    border-radius: 20px;
23	    background: #1f2229;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    height: 88px;
28	    margin-bottom: 16px;
29	    padding: 0 12px;
30	    display: flex;
31	    align-items: flex-end;
32	    justify-content: flex-end;
33	    overflow: hidden;
34	    color: #fff;
35	    font-size: 48px;
36	    font-weight: 300;
37	    white-space: nowrap;
38	    font-variant-numeric: tabular-nums;
39	  }
40	  .keys {
41	    display: grid;
42	    grid-template-columns: repeat(4, 1fr);
43	    gap: 10px;
44	  }
45	  button {
46	    height: 64px;
47	    border: 0;
48	    border-radius: 14px;
49	    font: inherit;
50	    font-size: 24px;
51	    color: #fff;
52	    background: #3a3f4a;
53	    cursor: pointer;
54	  }
55	  button:hover { filter: brightness(1.12); }
56	  button:active { filter: brightness(0.9); }
57	  button:focus-visible { outline: 2px solid #8ab4ff; outline-offset: 2px; }
58	  .op { background: #f59e0b; }
59	  .op.active { background: #fff; color: #f59e0b; }
60	  .fn { background: #a5a9b3; color: #1f2229; }
61	  .wide { grid-column: span 2; }
62	</style>
63	</head>
64	<body>
65	<div class="calc">
66	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" aria-live="polite">0</div>
67	  <div class="keys">
68	    <button class="fn wide" data-testid="key-lparen" data-action="lparen" aria-label="open parenthesis">(</button>
69	    <button class="fn wide" data-testid="key-rparen" data-action="rparen" aria-label="close parenthesis">)</button>
70	
71	    <button class="fn" data-testid="key-clear" data-action="clear">AC</button>
72	    <button class="fn" data-testid="key-sign" data-action="sign" aria-label="change sign">±</button>
73	    <button class="fn" data-testid="key-percent" data-action="percent" aria-label="percent">%</button>
74	    <button class="op" data-testid="key-div" data-op="/" aria-label="divide">÷</button>
75	
76	    <button data-testid="key-7" data-digit="7">7</button>
77	    <button data-testid="key-8" data-digit="8">8</button>
78	    <button data-testid="key-9" data-digit="9">9</button>
79	    <button class="op" data-testid="key-mul" data-op="*" aria-label="multiply">×</button>
80	
81	    <button data-testid="key-4" data-digit="4">4</button>
82	    <button data-testid="key-5" data-digit="5">5</button>
83	    <button data-testid="key-6" data-digit="6">6</button>
84	    <button class="op" data-testid="key-sub" data-op="-" aria-label="subtract">−</button>
85	
86	    <button data-testid="key-1" data-digit="1">1</button>
87	    <button data-testid="key-2" data-digit="2">2</button>
88	    <button data-testid="key-3" data-digit="3">3</button>
89	    <button class="op" data-testid="key-add" data-op="+" aria-label="add">+</button>
90	
91	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
92	    <button data-testid="key-dot" data-action="dot" aria-label="decimal point">.</button>
93	    <button class="op" data-testid="key-equals" data-action="equals" aria-label="equals">=</button>
94	  </div>
95	</div>
96	<script>
97	(function () {
98	  var display = document.querySelector('[data-testid="calc-display"]');
99	  var opButtons = document.querySelectorAll('[data-op]');
100	
101	  // entry: string being typed, or null when showing a stored value.
102	  // value: number currently shown when entry is null.
103	  // operand: true when value came from ± or % and is the next operand, like
104	  // a typed entry, but further digits start a new entry instead of appending.
105	  // groups: one saved { stored, op } per open parenthesis, innermost last.
106	  var state;
107	
108	  function reset() {
109	    state = { entry: null, value: 0, stored: null, op: null, operand: false, error: false, groups: [] };
110	  }
111	
112	  function compute(a, op, b) {
113	    switch (op) {
114	      case '+': return a + b;
115	      case '-': return a - b;
116	      case '*': return a * b;
117	      case '/': return a / b;
118	    }
119	    return b;
120	  }
121	
122	  function currentNumber() {
123	    return state.entry !== null ? parseFloat(state.entry) : state.value;
124	  }
125	
126	  // Presentation only: round to at most 10 significant digits for the visible
127	  // text. The stored value is never rounded, so chains stay exact.
128	  // Exponential notation only when the rounded magnitude is >= 1e10 or < 1e-9.
129	  function formatValue(n) {
130	    if (n === 0) return '0';
131	    var parts = Math.abs(n).toExponential(9).split('e');
132	    var digits = parts[0].replace('.', '');
133	    var exp = parseInt(parts[1], 10);
134	    var sign = n < 0 ? '-' : '';
135	    if (exp >= 10 || exp < -9) {
136	      var mantissa = trimFraction(digits.charAt(0), digits.slice(1));
137	      return sign + mantissa + 'e' + (exp < 0 ? '-' : '+') + Math.abs(exp);
138	    }
139	    if (exp >= 0) {
140	      return sign + trimFraction(digits.slice(0, exp + 1), digits.slice(exp + 1));
141	    }
142	    return sign + trimFraction('0', new Array(-exp).join('0') + digits);
143	  }
144	
145	  function trimFraction(intPart, frac) {
146	    frac = frac.replace(/0+$/, '');
147	    return frac ? intPart + '.' + frac : intPart;
148	  }
149	
150	  function render() {
151	    var text;
152	    if (state.error) {
153	      text = 'Error';
154	    } else if (state.entry !== null) {
155	      text = state.entry;
156	    } else {
157	      text = formatValue(state.value);
158	    }
159	    display.textContent = text;
160	    display.setAttribute('data-value', state.error ? 'NaN' : String(currentNumber()));
161	    display.setAttribute('data-error', state.error ? 'true' : 'false');
162	
163	    var len = text.length;
164	    display.style.fontSize = len > 16 ? '20px' : len > 12 ? '28px' : len > 9 ? '36px' : '48px';
165	
166	    for (var i = 0; i < opButtons.length; i++) {
167	      var b = opButtons[i];
168	      b.classList.toggle('active', state.entry === null && !state.operand && state.op === b.getAttribute('data-op'));
169	    }
170	  }
171	
172	  // In the error state every key except clear is ignored.
173	  function inputDigit(d) {
174	    if (state.error) return;
175	    state.operand = false;
176	    if (state.entry === null || state.entry === '0') {
177	      state.entry = d;
178	    } else if (state.entry === '-0') {
179	      state.entry = '-' + d;
180	    } else {
181	      state.entry += d;
182	    }
183	  }
184	
185	  function inputDot() {
186	    if (state.error) return;
187	    state.operand = false;
188	    if (state.entry === null) {
189	      state.entry = '0.';
190	    } else if (state.entry.indexOf('.') === -1) {
191	      state.entry += '.';
192	    }
193	  }
194	
195	  // ± and % act on the shown number at once. A typed entry keeps its text
196	  // under ±, so 0 ± 5 gives -5.
197	  function inputSign() {
198	    if (state.error) return;
199	    if (state.entry !== null) {
200	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
201	    } else {
202	      state.value = -state.value;
203	      state.operand = true;
204	    }
205	  }
206	
207	  function inputPercent() {
208	    if (state.error) return;
209	    state.value = currentNumber() / 100;
210	    state.entry = null;
211	    state.operand = true;
212	  }
213	
214	  function setResult(n) {
215	    if (!isFinite(n)) {
216	      reset();
217	      state.error = true;
218	      return;
219	    }
220	    state.value = n;
221	  }
222	
223	  // Immediate execution, strictly left to right, no operator precedence:
224	  // an operator key first applies the operation already waiting, so the
225	  // display always shows a real running result. 2 + 3 × 4 = is 20, not 14.
226	  function inputOp(op) {
227	    if (state.error) return;
228	    if (state.entry !== null || state.operand) {
229	      var n = currentNumber();
230	      state.entry = null;
231	      state.operand = false;
232	      if (state.op !== null && state.stored !== null) {
233	        setResult(compute(state.stored, state.op, n));
234	        if (state.error) return;
235	      } else {
236	        state.value = n;
237	      }
238	    }
239	    state.stored = state.value;
240	    state.op = op;
241	  }
242	
243	  // Finish the operation waiting at the current level, as = does.
244	  function finishLevel() {
245	    state.operand = false;
246	    if (state.op === null) {
247	      if (state.entry !== null) {
248	        state.value = parseFloat(state.entry);
249	        state.entry = null;
250	      }
251	      return;
252	    }
253	    var b = currentNumber();
254	    state.entry = null;
255	    var op = state.op;
256	    state.op = null;
257	    var a = state.stored;
258	    state.stored = null;
259	    setResult(compute(a, op, b));
260	  }
261	
262	  // ( saves the waiting operation and starts a fresh one inside the group.
263	  // Right after a number, ( multiplies it by the group: 2 ( 3 ) is 6.
264	  function openGroup() {
265	    if (state.error) return;
266	    if (state.entry !== null || state.operand) {
267	      inputOp('*');
268	      if (state.error) return;
269	    }
270	    state.groups.push({ stored: state.stored, op: state.op });
271	    state.entry = null;
272	    state.value = 0;
273	    state.stored = null;
274	    state.op = null;
275	    state.operand = false;
276	  }
277	
278	  // ) finishes the group and hands its result back as the next operand.
279	  function closeGroup() {
280	    if (state.error || state.groups.length === 0) return;
281	    finishLevel();
282	    if (state.error) return;
283	    var outer = state.groups.pop();
284	    state.stored = outer.stored;
285	    state.op = outer.op;
286	    state.operand = true;
287	  }
288	
289	  // = closes any groups still open, then finishes the calculation.
290	  function equals() {
291	    if (state.error) return;
292	    while (state.groups.length > 0) {
293	      closeGroup();
294	      if (state.error) return;
295	    }
296	    finishLevel();
297	  }
298	
299	  document.querySelector('.keys').addEventListener('click', function (e) {
300	    var btn = e.target.closest('button');
301	    if (!btn) return;
302	    if (btn.hasAttribute('data-digit')) inputDigit(btn.getAttribute('data-digit'));
303	    else if (btn.hasAttribute('data-op')) inputOp(btn.getAttribute('data-op'));
304	    else {
305	      var action = btn.getAttribute('data-action');
306	      if (action === 'dot') inputDot();
307	      else if (action === 'sign') inputSign();
308	      else if (action === 'percent') inputPercent();
309	      else if (action === 'lparen') openGroup();
310	      else if (action === 'rparen') closeGroup();
311	      else if (action === 'equals') equals();
312	      else if (action === 'clear') reset();
313	    }
314	    render();
315	  });
316	
317	  document.addEventListener('keydown', function (e) {
318	    if (e.ctrlKey || e.metaKey || e.altKey) return;
319	    var k = e.key;
320	    if (/^[0-9]$/.test(k)) inputDigit(k);
321	    else if (k === '.' || k === ',') inputDot();
322	    else if (k === '+' || k === '-' || k === '*' || k === '/') inputOp(k);
323	    else if (k === '%') inputPercent();
324	    else if (k === '(') openGroup();
325	    else if (k === ')') closeGroup();
326	    else if (k === 'Enter' || k === '=') equals();
327	    else if (k === 'Escape' || k === 'c' || k === 'C') reset();
328	    else return;
329	    e.preventDefault();
330	    render();
331	  });
332	
333	  reset();
334	  render();
335	})();
336	</script>
337	</body>
338	</html>
